{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/publication.py; cloud_pilot/live/engine.py",
      "detail": "seal_research publishes an immutable RESEARCH_READY.json with WRITING_AI_READY=true before the mandatory independent fact review. The same file says that review is pending, while the handoff reports research_locked=false and the durable research lock remains active. A rejected proposal can therefore remain available as an apparently ready canonical handoff.",
      "required_fix": "Persist the proposal as locked and not writing-ready. After independent fact acceptance, publish a final research handoff and review record with consistent readiness and lock fields, and bind writing to that completion commit."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/engine.py; cloud_pilot/multilingual/localize.py; cloud_pilot/multilingual/editorial_state.py",
      "detail": "Research can begin after the last editorial.check but while a writing or localization model call is in flight. The English path can checkpoint the stale article and call its reviewer before checking the changed research head again. Publication is subsequently fenced, but stale work and paid review can occur during research remediation.",
      "required_fix": "Fence model-stage starts against research mutation, and recheck the research fence immediately after each writing or localization call and before checkpointing or initiating review. Add interleaving tests for these active paths."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/engine.py; cloud_pilot/multilingual/localize.py; cloud_pilot/multilingual/editorial_state.py",
      "detail": "A delivery failure leaves the publication fence active. If the cached source evidence expires before recovery, the old epoch cannot pass evidence validation, while a new research epoch cannot begin because the fence blocks research mutations. No verified cancellation or reconciliation path is provided to release that fence.",
      "required_fix": "Implement an operator-authorized, auditable recovery or abort protocol that verifies or invalidates partially created draft artifacts before releasing the fence. Test recovery after evidence expiry, including a new research epoch."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/stages.py; cloud_pilot/live/engine.py; cloud_pilot/multilingual/publication.py",
      "detail": "check_research rejects RESEARCH_FAIL or writing_ai_ready=false before a research packet is persisted. The engine records only a generic halt, so a failed article does not receive the required canonical verdict, blocked facts, source log and handoff.",
      "required_fix": "Persist every research verdict, including FAIL and non-ready CONDITIONAL, under the research file boundary with its fact sheet, source log, blocked facts and handoff. Keep writing disabled until a fresh eligible version is completed."
    },
    {
      "severity": "high",
      "file": ".github/workflows/cloud-pilot-trusted.yml; cloud_pilot/multilingual/startup.py",
      "detail": "The mandatory startup sequence requires a git pull before research and writing. The workflow checks out a pinned revision, and startup.verify compares local and remote-tracking identifiers, but the supplied active path does not perform the required pull. It nevertheless records PRE_RESEARCH_SYNC_PASS.",
      "required_fix": "Implement the prescribed main synchronization sequence before research, verify the live origin head and record the actual resulting identifiers. Fail the startup gate if synchronization cannot be completed."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
